// Surface-selection details panel markup (Suitable surfaces colour mode).
// Pure function so node tests can assert the panel without a DOM.

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}

function format(value, digits = 1) {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return '—';
  return new Intl.NumberFormat('en-GB', { maximumFractionDigits: digits }).format(Number(value));
}

export function surfaceDetailsMarkup(record, buildingId) {
  const head = `<div class="details-head"><span class="eyebrow">Selected surface</span><h2>${esc(record?.id ?? '(surface)')}</h2><p>${esc(buildingId ?? '')}</p></div>`;
  if (!record) {
    return `${head}<section class="detail-section"><div class="empty-note">This surface is not part of the SolarPotential export for the selected input dataset, so no surface results are available.</div></section>`;
  }
  if (!record.suitable) {
    return `${head}<section class="detail-section"><div class="empty-note">This surface is <strong>not suitable for solar panels</strong> under the SimStadt analysis for the selected input dataset — its surfaces were removed by the minimum insolation or area filters, so no surface results exist.</div></section>`;
  }
  return `${head}<section class="detail-section"><h3 class="section-title">SolarPotential surface details</h3><div class="scenario-value"><span>Surface type</span><strong>${esc(record.type || '—')}</strong></div><div class="scenario-value"><span>Suitability</span><strong>suitable (passed the SimStadt filters)</strong></div><div class="scenario-value"><span>Surface area</span><strong>${format(record.area)} <small>m²</small></strong></div><div class="scenario-value"><span>Annual irradiation</span><strong>${format(record.irradiation)} <small>kWh/m²/yr</small></strong></div></section>`;
}
