import { VectorTile } from '@mapbox/vector-tile';
import { PbfReader } from 'pbf';
import { PMTiles } from 'pmtiles';
import * as Cesium from 'cesium';

const TILE_SIZE = 256;
const MAP_BOUNDS = [-73.4733, 5.4203, -73.2601, 5.65];
const FILL_STYLES = [
  ['landcover', '#9fc394', 0.95],
  ['landuse', '#eee0bd', 0.94],
  ['park', '#82bd70', 0.96],
  ['water', '#70c3dc', 0.96],
  ['building', '#d9ceb0', 0.98],
];

function blankTile() {
  const canvas = document.createElement('canvas');
  canvas.width = TILE_SIZE;
  canvas.height = TILE_SIZE;
  const context = canvas.getContext('2d');
  context.fillStyle = '#c9d9bf';
  context.fillRect(0, 0, TILE_SIZE, TILE_SIZE);
  return { canvas, context };
}

function drawLayer(context, layer, extent, style) {
  if (!layer) return;
  const scale = TILE_SIZE / extent;
  context.save();
  context.scale(scale, scale);
  for (let index = 0; index < layer.length; index += 1) {
    const feature = layer.feature(index);
    if (feature.type !== 3) continue;
    context.beginPath();
    for (const ring of feature.loadGeometry()) {
      if (!ring.length) continue;
      context.moveTo(ring[0].x, ring[0].y);
      for (let point = 1; point < ring.length; point += 1) {
        context.lineTo(ring[point].x, ring[point].y);
      }
      context.closePath();
    }
    context.globalAlpha = style.opacity;
    context.fillStyle = style.fill;
    context.fill('evenodd');
    if (style.outline) {
      context.globalAlpha = 1;
      context.strokeStyle = style.outline;
      context.lineWidth = extent / TILE_SIZE;
      context.stroke();
    }
  }
  context.restore();
}

function drawLines(context, layer, extent, styleForFeature) {
  if (!layer) return;
  const scale = TILE_SIZE / extent;
  context.save();
  context.scale(scale, scale);
  for (let index = 0; index < layer.length; index += 1) {
    const feature = layer.feature(index);
    if (feature.type !== 2) continue;
    const style = styleForFeature(feature.properties);
    if (!style) continue;
    for (const line of feature.loadGeometry()) {
      if (!line.length) continue;
      context.beginPath();
      context.moveTo(line[0].x, line[0].y);
      for (let point = 1; point < line.length; point += 1) {
        context.lineTo(line[point].x, line[point].y);
      }
      context.strokeStyle = style.color;
      context.lineWidth = style.width * extent / TILE_SIZE;
      context.lineCap = 'round';
      context.lineJoin = 'round';
      context.stroke();
    }
  }
  context.restore();
}

function renderVectorTile(bytes, zoom) {
  const { canvas, context } = blankTile();
  const tile = new VectorTile(new PbfReader(new Uint8Array(bytes)));
  const extent = tile.layers.landcover?.extent
    ?? tile.layers.landuse?.extent
    ?? tile.layers.transportation?.extent
    ?? 4096;

  for (const [id, fill, opacity] of FILL_STYLES) {
    drawLayer(context, tile.layers[id], extent, {
      fill,
      opacity,
      outline: id === 'building' ? '#918b7c' : undefined,
    });
  }

  drawLines(context, tile.layers.waterway, extent, () => ({ color: '#429dbb', width: 1.25 }));
  drawLines(context, tile.layers.transportation, extent, (properties) => {
    if (!['primary', 'secondary', 'tertiary', 'trunk', 'motorway'].includes(properties.class)) return undefined;
    return { color: '#a88e5e', width: Math.max(2.2, (zoom - 6) * 0.34) };
  });
  drawLines(context, tile.layers.transportation, extent, (properties) => {
    const major = ['primary', 'secondary', 'tertiary', 'trunk', 'motorway'].includes(properties.class);
    if (major) return { color: '#fffdf7', width: Math.max(1.35, (zoom - 6) * 0.23) };
    return { color: '#fff9e9', width: Math.max(0.85, (zoom - 8) * 0.12) };
  });
  drawLines(context, tile.layers.boundary, extent, () => ({ color: '#9c7668', width: 1.1 }));
  return canvas;
}

export async function createPmtilesImageryProvider(archiveUrl) {
  const archive = new PMTiles(archiveUrl);
  const header = await archive.getHeader();
  if (header.tileType !== 1) {
    throw new Error(`Expected vector tiles in ${archiveUrl}; PMTiles tile type is ${header.tileType}.`);
  }

  const errorEvent = new Cesium.Event();
  const provider = {
    ready: true,
    readyPromise: Promise.resolve(true),
    rectangle: Cesium.Rectangle.fromDegrees(...MAP_BOUNDS),
    tileWidth: TILE_SIZE,
    tileHeight: TILE_SIZE,
    minimumLevel: header.minZoom,
    maximumLevel: header.maxZoom,
    tilingScheme: new Cesium.WebMercatorTilingScheme(),
    tileDiscardPolicy: undefined,
    errorEvent,
    credit: new Cesium.Credit('© OpenStreetMap contributors · BBBike extract · systemed/BBBike.org style', true),
    proxy: undefined,
    hasAlphaChannel: true,
    getTileCredits: () => undefined,
    async requestImage(x, y, level) {
      const result = await archive.getZxy(level, x, y);
      if (!result) return blankTile().canvas;
      try {
        return renderVectorTile(result.data, level);
      } catch (error) {
        errorEvent.raiseEvent({ x, y, level, message: error.message, error });
        return blankTile().canvas;
      }
    },
  };

  return provider;
}
