// Keep the GPU-side tile cache bounded so navigation can release off-view content.
export const TILE_CACHE_OPTIONS = Object.freeze({
  cacheBytes: 128 * 1024 * 1024,
  maximumCacheOverflowBytes: 32 * 1024 * 1024,
});

function numeric(value) {
  if (value === null || value === undefined || value === '') return NaN;
  return Number(value);
}

// Sequential ramp: the Schemecolor "Red, Orange And Blue" palette extended to
// 8 breaks (two interpolated transition tones). No white or near-white stop —
// white stays reserved for buildings without a suitable solar result.
const COLOUR_STOPS = Object.freeze([
  '#2d55cc', '#3a68d8', '#487be3', '#a1938b', '#faab33', '#f99244', '#ff6a4c', '#ff4041',
]);
const FLOOR_COLOUR = '#faab33';
const DIVERGE_NEGATIVE = '#487be3';
const DIVERGE_POSITIVE = '#ff4041';
const DIVERGE_CENTER = '#faab33';

export function createTileStyler(Cesium) {
  function colourFor(value, min, max) {
    if (!Number.isFinite(value)) return Cesium.Color.WHITE;
    if (max === min) return Cesium.Color.fromCssColorString(FLOOR_COLOUR);
    const t = Math.max(0, Math.min(1, (value - min) / (max - min)));
    const segments = COLOUR_STOPS.length - 1;
    const index = Math.min(segments - 1, Math.floor(t * segments));
    const local = t * segments - index;
    return Cesium.Color.lerp(
      Cesium.Color.fromCssColorString(COLOUR_STOPS[index]),
      Cesium.Color.fromCssColorString(COLOUR_STOPS[index + 1]),
      local,
      new Cesium.Color(),
    );
  }

  function styleFeature(feature, state, metricData, selectedId, surfaces) {
    // Batch features carry numeric indices into the scenario's surface
    // catalog (b = building row, s = surface row, -1 = unmodelled). Legacy
    // tile sets (e.g. the demo bundle) still expose string building ids.
    const buildingIndex = feature.getProperty('b');
    const surfaceIndex = feature.getProperty('s');
    let buildingId;
    let surfaceRecord;
    if (typeof buildingIndex === 'number') {
      if (!surfaces) return;  // catalog not available: stay unstyled
      buildingId = surfaces.buildings[buildingIndex];
      surfaceRecord = surfaces.surfaces[surfaceIndex] ?? null;
      if (buildingId === undefined) return;
    } else {
      buildingId = feature.getProperty('building_id');
      if (buildingId === undefined) return;
    }
    feature.show = true;
    if (state.mode === 'surface') {
      // Only the clicked surface is highlighted; the rest of the building
      // keeps its colours.
      if (buildingId === selectedId && String(surfaceIndex) === String(state.selectedSurfaceIndex)) {
        feature.color = Cesium.Color.fromCssColorString('#00e5ff');
        return;
      }
      if (!Number.isFinite(state.min) || !Number.isFinite(state.max)) {
        feature.color = Cesium.Color.WHITE;  // scale not ready: stay neutral pending catalog
        return;
      }
      if (!surfaceRecord || !surfaceRecord.suitable || !Number.isFinite(numeric(surfaceRecord.irradiation))) {
        feature.color = Cesium.Color.WHITE;
        return;
      }
      feature.color = colourFor(numeric(surfaceRecord.irradiation), state.min, state.max);
      return;
    }
    if (buildingId && buildingId === selectedId) {
      feature.color = Cesium.Color.fromCssColorString('#00e5ff');
      feature.show = true;
      return;
    }
    const building = metricData.buildings[buildingId];
    const mode = state.mode ?? (state.diff ? 'difference' : 'scenario');
    if (mode === 'surface') {
      // Only SolarPotential-suitable surfaces are coloured, each by its own
      // annual irradiation on the shared scale; everything else stays neutral.
      if (!Number.isFinite(state.min) || !Number.isFinite(state.max)) {
        feature.color = Cesium.Color.WHITE;  // scale not ready: stay neutral pending catalog
        return;
      }
      if (!surfaceRecord || !surfaceRecord.suitable || !Number.isFinite(numeric(surfaceRecord.irradiation))) {
        feature.color = Cesium.Color.WHITE;
        return;
      }
      feature.color = colourFor(numeric(surfaceRecord.irradiation), state.min, state.max);
      return;
    }
    const value = numeric(building?.scenarios?.[state.active]);
    const reference = numeric(building?.scenarios?.[state.reference]);
    const metric = mode === 'difference' && Number.isFinite(value) && Number.isFinite(reference)
      ? value - reference
      : value;
    if (!Number.isFinite(metric)) {
      feature.color = Cesium.Color.WHITE;
      feature.show = true;
      return;
    }
    const t = state.max === state.min ? 0.5 : Math.max(0, Math.min(1, (metric - state.min) / (state.max - state.min)));
    if (mode === 'difference') {
      const diverge = metric < 0 ? DIVERGE_NEGATIVE : DIVERGE_POSITIVE;
      feature.color = Cesium.Color.lerp(
        Cesium.Color.fromCssColorString(DIVERGE_CENTER),
        Cesium.Color.fromCssColorString(diverge),
        Math.abs(t - 0.5) * 2,
        new Cesium.Color(),
      );
    } else {
      feature.color = colourFor(metric, state.min, state.max);
    }
    feature.show = true;
  }

  /** Styles visible content on demand; it retains no tile or feature references. */
  function attachTileStyling(tileset, scenarioId, getState, getMetricData, getSelectedId, getSurfaces) {
    return tileset.tileVisible.addEventListener((tile) => {
      const state = getState();
      if (scenarioId !== state.shown) return;
      for (let index = 0; index < tile.content.featuresLength; index += 1) {
        const feature = tile.content.getFeature(index);
        if (feature.getProperty('building_id') || feature.getProperty('b') !== undefined) {
          styleFeature(feature, state, getMetricData(), getSelectedId(),
            getSurfaces ? getSurfaces(scenarioId) : null);
        }
      }
    });
  }

  return { attachTileStyling, colourFor, styleFeature };
}
